import { getCachedToken, ensureValidSession, getLastAuthExchangeError, triggerReauthPrompt, wasLastAuthExchangeTransientFailure } from './auth-session';

const fetch = async (input: RequestInfo | URL, init?: RequestInit): Promise<Response> => {
    const urlStr = typeof input === "string" ? input : (input instanceof URL ? input.toString() : (input as Request)?.url || "");
    const isAuthEndpoint = urlStr.includes("/api/auth/");
    const isRetry = Boolean((init as { _isRetry?: boolean })?._isRetry);

    let token = getCachedToken();
    if (!token && typeof window !== "undefined" && !isAuthEndpoint) {
        token = await ensureValidSession().catch(() => null);
    }
    if (token) {
        if (init?.headers instanceof Headers) {
            if (!init.headers.has("Authorization")) {
                init.headers.set("Authorization", `Bearer ${token}`);
            }
        } else if (Array.isArray(init?.headers)) {
            const hasAuth = init.headers.some(([k]) => k.toLowerCase() === "authorization");
            if (!hasAuth) {
                init.headers.push(["Authorization", `Bearer ${token}`]);
            }
        } else {
            init = {
                ...init,
                headers: {
                    ...(init?.headers as Record<string, string>),
                    Authorization: `Bearer ${token}`
                }
            };
        }
    }
    const activeFetch = typeof globalThis !== "undefined" && globalThis.fetch ? globalThis.fetch : (typeof window !== "undefined" ? window.fetch : undefined);
    if (!activeFetch) {
        throw new Error("No fetch implementation available");
    }
    const res = await activeFetch(input, init);
    // 🛡️ 401 自動換票與自癒重試防禦 (Self-Healing Recovery & 1-time Re-execution)
    if (res.status === 401 && typeof window !== "undefined" && !urlStr.includes("/api/ai/test-key")) {
        // 區分「Gemini API Key 無效 (401)」vs「Tabiji Session JWT 過期 (401)」，絕不因用戶端 AI 金鑰過期而誤刪 Session Token
        const peekData = typeof res.clone === "function" ? await res.clone().json().catch(() => null) : null;
        const detailText = String((peekData as { detail?: string } | null)?.detail || "").toLowerCase();
        if (detailText.includes("gemini") || detailText.includes("api key") || detailText.includes("金鑰")) {
            return res;
        }
        console.warn("⚠️ [API] Received 401 Unauthorized from backend...");

        // 🛑 遞迴熔斷防護：認證端點本身或已重試過的請求禁止再次觸發換票重試
        const isBodyConsumed = typeof Request !== "undefined" && input instanceof Request && input.bodyUsed;
        if (!isAuthEndpoint && !isRetry && !isBodyConsumed) {
            // 注意：保留現有 Token 作為持有證明 (PoP) 供 ensureValidSession 驗簽
            const freshToken = await ensureValidSession(true).catch(() => null);
            if (freshToken) {
                let nextHeaders: Headers;
                if (init?.headers instanceof Headers) {
                    nextHeaders = new Headers(init.headers);
                } else if (Array.isArray(init?.headers)) {
                    nextHeaders = new Headers(init.headers);
                } else {
                    nextHeaders = new Headers((init?.headers as Record<string, string>) || {});
                }
                nextHeaders.set("Authorization", `Bearer ${freshToken}`);
                const retryInit = {
                    ...init,
                    headers: nextHeaders,
                    _isRetry: true
                } as RequestInit & { _isRetry?: boolean };
                return activeFetch(input, retryInit);
            } else if (!urlStr.includes("/api/poi/")) {
                // 🛡️ 換票失敗：僅在後端明確拒收憑證 (非 5xx/離線等暫態錯誤) 時才清除 Token 並喚起重認證視窗
                const isTransientFailure = typeof wasLastAuthExchangeTransientFailure === "function" && wasLastAuthExchangeTransientFailure();
                if (!isTransientFailure) {
                    localStorage.removeItem("tabiji_session_token");
                    triggerReauthPrompt(
                        getLastAuthExchangeError() || "您的憑證已失效或已在其他裝置輪替更新，請輸入最新引繼碼。"
                    );
                }
            }
        }
    }
    return res;
};


